-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 16
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 16 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 16', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 16 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-16.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Defina escopo com suas palavras, citando o que ele determina em UI/UX', 0.2, 'Escopo é o acordo que define exatamente o trabalho a ser realizado e as entregas esperadas. Em UI/UX, determina quais telas, formulários, botões e jornadas existirão no produto final.', 'Nota cheia: define escopo como acordo sobre o trabalho e as entregas e cita que ele determina telas, formulários, botões ou jornadas em UI/UX, com as próprias palavras. Metade: define escopo como conjunto de entregas ou telas, mas não relaciona com UI/UX. Zero: em branco, definição errada ou fora do tema.'),
      (v_atividade, 1, 2, 'Explique o que acontece com o projeto quando não há escopo definido', 0.4, 'Sem escopo definido, o projeto nunca chega ao fim: a equipe fala em "fazer um pouco de tudo", surgem pedidos sem limite e o trabalho se estende sem entrega.', 'Nota cheia: afirma que sem escopo o projeto não chega ao fim (ou não tem fim) e explica a consequência, como pedidos sem limite, retrabalho ou falta de entrega clara. Metade: fala de confusão ou atraso sem ligar ao fim do projeto. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 3, 'Dê um exemplo de entrega que deve constar no escopo de um agendador', 0.4, 'Um exemplo de entrega do escopo de um agendador, como a lista clara de serviços e valores, a grade de dias e horários livres ou a tela de resumo e confirmação com cancelamento simples.', 'Nota cheia: dá um exemplo de entrega coerente com o agendador (serviços, horários livres, confirmação, comprovante ou cancelamento) e explica por que ele está no escopo. Metade: dá um exemplo genérico ou sem relação clara com o agendador. Zero: em branco, exemplo de algo que a aula coloca fora da versão 1 (pagamento, rede social, jogos, chat aberto) ou fora do tema.'),
      (v_atividade, 2, 1, 'Defina fronteira com as suas palavras', 0.2, 'Fronteira é o limite exato que divide o que faz parte do sistema daquilo que está fora dele.', 'Nota cheia: define fronteira como limite exato entre o que está dentro e o que está fora do sistema, com as próprias palavras. Metade: define de forma vaga, como "uma linha" ou "um limite", sem separar dentro e fora. Zero: em branco, definição errada ou fora do tema.'),
      (v_atividade, 2, 2, 'Diga por que a fronteira precisa ser um limite exato, e não uma ideia vaga', 0.4, 'A fronteira precisa ser exata porque uma ideia vaga gera ambiguidade: cada pessoa entende uma coisa diferente e o que deve ser entregue fica indefinido, abrindo espaço para pedidos extras.', 'Nota cheia: explica que o limite exato evita ambiguidade e interpretações diferentes, e que uma ideia vaga abre espaço para pedidos extras ou retrabalho. Metade: diz apenas que o limite exato é "mais claro" sem explicar o efeito. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 3, 'Mostre como a fronteira protege o foco da equipe durante o design', 0.4, 'A fronteira protege o foco porque deixa claro o que a equipe deve desenhar e o que não deve, evitando que funções fora do escopo desviem a atenção durante o design.', 'Nota cheia: mostra que a fronteira define o que desenhar e o que deixar de fora, e que isso evita desvio de foco durante o design. Metade: menciona foco ou organização sem ligar à fronteira. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 1, 'Defina prioridade com as suas palavras', 0.2, 'Prioridade é a ordem de importância técnica e de valor para construir primeiro o que é vital.', 'Nota cheia: define prioridade como ordem de importância (técnica e de valor) para construir primeiro o que é essencial, com as próprias palavras. Metade: define só como "ordem" ou "o que vem primeiro", sem o critério de importância. Zero: em branco, definição errada ou fora do tema.'),
      (v_atividade, 3, 2, 'Explique o critério técnico e de valor usado para definir o que construir primeiro', 0.4, 'O critério técnico considera o que o sistema precisa para funcionar, e o de valor considera o que o usuário precisa para concluir a ação principal. Assim, constrói-se primeiro o que é vital.', 'Nota cheia: cita os dois critérios, técnico (o que o sistema precisa para funcionar) e de valor (o que entrega valor ao usuário), com as próprias palavras. Metade: cita só um dos critérios ou fala de "importância" sem separar. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 3, 'Diga o que se perde quando a prioridade é ignorada', 0.4, 'Quando a prioridade é ignorada, a equipe constrói recursos secundários antes dos vitais, o sistema pode ficar sem o essencial, o prazo estoura e o usuário não consegue concluir a ação principal.', 'Nota cheia: explica que ignorar a prioridade faz a equipe construir o secundário antes do vital, com perda de prazo ou de funcionalidade essencial. Metade: diz apenas que "atrasa" ou "piora" sem explicar o que se perde. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 1, 'Defina delimitação com suas palavras', 0.2, 'Delimitação é a ação prática de dizer não a pedidos secundários para proteger o foco da equipe.', 'Nota cheia: define delimitação como ação prática de recusar pedidos secundários para proteger o foco, com as próprias palavras. Metade: define de forma genérica, como "colocar limites", sem ligar ao foco ou aos pedidos secundários. Zero: em branco, definição errada ou fora do tema.'),
      (v_atividade, 4, 2, 'Explique o que significa "dizer não a pedidos secundários"', 0.4, 'Dizer não a pedidos secundários é recusar ou adiar o que não resolve a dor principal dos usuários, mantendo a equipe concentrada no que é vital.', 'Nota cheia: explica que é recusar ou adiar pedidos que não resolvem a dor principal, sem perder o foco do projeto. Metade: fala de "dizer não" de forma genérica, sem relacionar à dor principal. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 3, 'Diga como a delimitação protege a equipe de atrasos', 0.4, 'A delimitação protege a equipe de atrasos porque evita a entrada de recursos que não foram analisados, reduz o trabalho desnecessário e permite entregar o essencial dentro do prazo.', 'Nota cheia: liga a delimitação a menos trabalho desnecessário e a entrega no prazo, evitando atraso causado por pedidos secundários. Metade: diz que "evita atraso" sem explicar o mecanismo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 1, 'Cite o critério de funções centrais', 0.2, 'O critério de funções centrais inclui os recursos indispensáveis para solucionar o problema primário identificado na pesquisa.', 'Nota cheia: diz que entram as funções indispensáveis para resolver o problema primário identificado na pesquisa. Metade: diz que entram "funções importantes" sem ligar ao problema da pesquisa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 2, 'Explique o critério de jornada crítica, dando um exemplo de tela ou clique essencial', 0.4, 'O critério de jornada crítica reúne as telas e os cliques essenciais para que o usuário conclua a ação principal de ponta a ponta. Exemplo: a tela de escolha de horário livre ou o toque que confirma o agendamento.', 'Nota cheia: explica que a jornada crítica reúne telas e cliques para concluir a ação principal de ponta a ponta e dá um exemplo de tela ou clique essencial do agendador. Metade: explica o critério, mas sem exemplo, ou dá exemplo sem explicar. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 3, 'Explique o critério de alta viabilidade', 0.4, 'O critério de alta viabilidade inclui os itens que a equipe consegue desenhar, prototipar e validar com os recursos e o prazo atuais.', 'Nota cheia: explica que entram itens que a equipe consegue desenhar, prototipar e validar dentro dos recursos e do prazo atuais. Metade: fala de "fácil de fazer" sem citar prototipar ou validar nem prazo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 1, 'Cite o critério de ideias secundárias', 0.2, 'Ideias secundárias são recursos legais, mas que não resolvem o objetivo principal do usuário neste momento.', 'Nota cheia: define ideias secundárias como recursos que não resolvem o objetivo principal do usuário neste momento. Metade: diz apenas que são "ideias extras" sem relacionar ao objetivo principal. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 2, 'Explique o critério de alta complexidade e por que ele pode ser motivo de corte', 0.4, 'Recursos de alta complexidade têm regras de negócio que demandariam semanas de trabalho fora do prazo, por isso podem ser cortados da versão inicial.', 'Nota cheia: explica que alta complexidade significa muito trabalho (semanas) fora do prazo e que isso justifica o corte. Metade: diz que é "difícil" ou "demorado" sem ligar ao prazo ou ao corte. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 3, 'Explique o critério de pedidos sem dados, relacionando-o com a pesquisa com usuários', 0.4, 'Pedidos sem dados são opiniões isoladas que não foram validadas na pesquisa com usuários. Por isso, devem ficar de fora até que os dados comprovem que resolvem uma necessidade real.', 'Nota cheia: explica que pedidos sem dados são opiniões não validadas pela pesquisa com usuários e que, por isso, saem do escopo inicial. Metade: explica o critério sem relacionar à pesquisa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 1, 'Explique a camada Essencial', 0.2, 'A camada Essencial (Must) reúne o que é indispensável: sem isso o sistema não funciona e não cumpre seu papel básico.', 'Nota cheia: explica que Essencial é o indispensável, sem o qual o sistema não funciona ou não cumpre seu papel básico. Metade: diz que é "importante" ou "principal" sem ligar ao funcionamento básico. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 2, 'Explique a diferença entre a camada Importante e a Desejável', 0.4, 'A camada Importante agrega alto valor, mas admite contornos manuais temporários. A Desejável reúne melhorias de conveniência que só entram se sobrar tempo hábil.', 'Nota cheia: diferencia as duas: Importante tem alto valor e aceita contorno manual temporário; Desejável é conveniência e só entra se sobrar tempo. Metade: diferencia apenas por "importância", sem o contorno manual ou o tempo sobrando. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 3, 'Explique o que significa estar na camada Fora de Escopo', 0.4, 'Estar em Fora de Escopo (Won''t) significa que foi decidido expressamente que o item não será feito nesta versão inicial.', 'Nota cheia: explica que é uma decisão expressa de não fazer o item nesta versão inicial. Metade: diz que "não entra" sem falar em decisão expressa ou nesta versão. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 1, 'Defina inchaço de escopo com suas palavras', 0.2, 'Inchaço de escopo (scope creep) é o aumento descontrolado de pedidos e funções adicionadas sem análise, que gera atraso e confusão.', 'Nota cheia: define inchaço como aumento descontrolado de funções ou pedidos sem análise, que gera atraso e confusão. Metade: define só como "crescimento do projeto" sem o descontrole ou a falta de análise. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 2, 'Explique como os pedidos extras sem análise de impacto levam a atrasos', 0.4, 'Pedidos extras entram sem análise de impacto, o que sobrecarrega a equipe e estoura prazos. Assim, o trabalho cresce mais que o tempo disponível e a entrega atrasa.', 'Nota cheia: mostra a cadeia pedido sem análise de impacto, sobrecarga da equipe e prazo estourado. Metade: liga pedidos extras a atraso sem explicar a cadeia. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 3, 'Explique como o inchaço chega até o usuário final, deixando a interface confusa', 0.4, 'Com o inchaço, surgem botões e fluxos extras que não funcionam bem. O usuário fica perdido e a interface se torna confusa.', 'Nota cheia: mostra a cadeia do inchaço até o usuário final, com telas, botões ou fluxos extras que confundem o usuário. Metade: diz que "a interface fica confusa" sem explicar como o inchaço chega até ela. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 1, 'Explique o que é carga cognitiva e como um escopo enxuto a reduz', 0.2, 'Carga cognitiva é o esforço mental para entender e decidir na tela. Um escopo enxuto a reduz, porque o usuário encontra o que procura em segundos, sem se perder.', 'Nota cheia: define carga cognitiva como esforço mental do usuário e explica que o escopo enxuto reduz esse esforço por ter menos opções. Metade: define carga cognitiva sem ligar ao escopo enxuto. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 2, 'Explique por que fluxos lineares reduzem as chances de erro', 0.4, 'Fluxos lineares, com um passo depois do outro, dão uma rota clara de navegação e reduzem as chances de erro do usuário.', 'Nota cheia: explica que o fluxo linear dá uma rota clara e que isso reduz os erros de navegação. Metade: diz que o fluxo "é mais simples" sem ligar a erros. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 3, 'Explique como poucos elementos bem refinados contribuem para a qualidade visual', 0.4, 'Poucos elementos bem desenhados, com espaçamento e contraste adequados, geram refinamento visual. Assim, a qualidade do conjunto aumenta mais do que com muitos elementos mal cuidados.', 'Nota cheia: explica que poucos elementos bem refinados (espaçamento e contraste) elevam a qualidade visual. Metade: diz que "fica mais bonito" sem citar refinamento, espaçamento ou contraste. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 1, 'Diga quais são as duas perguntas da matriz', 0.2, 'As duas perguntas da matriz são: qual o valor real que o item entrega para quem usa a interface, e qual o esforço técnico necessário para desenhar e programar.', 'Nota cheia: cita as duas perguntas: valor real para quem usa e esforço técnico para desenhar e programar. Metade: cita só uma das perguntas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 2, 'Explique o que é valor real para quem usa a interface', 0.4, 'Valor real é o que o item entrega para quem usa a interface, como ajudar a concluir o agendamento sem esforço. Não é o que parece bonito ou o que a equipe acha interessante.', 'Nota cheia: explica valor real como benefício concreto para quem usa a interface, ligado à tarefa do usuário. Metade: diz que é "importância" ou "utilidade" sem ligar ao usuário. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 3, 'Explique por que o foco deve estar em itens de alto valor e baixo ou médio esforço', 0.4, 'O foco deve estar em itens de alto valor e baixo ou médio esforço, porque geram o maior retorno para o usuário com o menor custo técnico, dentro do prazo.', 'Nota cheia: explica que alto valor com baixo ou médio esforço entrega mais resultado com menos custo e prazo. Metade: diz apenas que "o alto valor é melhor" sem considerar o esforço. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 1, 'Diga o que os percentuais de importância indicam sobre cada funcionalidade', 0.2, 'Os percentuais indicam o quanto os usuários consideram cada funcionalidade importante. A escolha de horário, com 95%, é muito importante; o chat de suporte, com 19%, tem baixa importância.', 'Nota cheia: explica que o percentual mede a importância atribuída pelos usuários e compara os dois casos (escolha de horário alta, chat baixo). Metade: explica o percentual sem comparar ou sem citar os números. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 2, 'Explique por que a escolha de horário deve estar no escopo inicial', 0.4, 'A escolha de horário deve estar no escopo inicial porque tem importância alta (95%) e resolve a dor principal: agendar com rapidez, visualizando horários livres sem precisar ligar.', 'Nota cheia: liga a escolha de horário ao percentual alto e à dor principal (agendar rápido, com horários livres). Metade: diz que deve entrar por ser importante, sem ligar à dor principal ou ao percentual. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 3, 'Explique por que um recurso com pouca importância para os usuários deve ser avaliado com cuidado antes de entrar', 0.4, 'Recurso pouco importante para os usuários pode não resolver nenhuma necessidade validada e pode poluir a tela. Por isso, deve ser avaliado com cuidado antes de entrar no escopo.', 'Nota cheia: explica que recurso de baixa importância pode não resolver necessidade validada e poluir a interface, por isso exige análise antes de entrar. Metade: diz apenas que "não é prioridade" sem a análise nem o risco de poluição. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 1, 'Explique a declaração de objetivo, indicando a meta de tempo e de etapas do fluxo', 0.2, 'A declaração de objetivo define o que se quer alcançar, com metas de tempo e de etapas. Exemplo da aula: criar um fluxo intuitivo de 3 passos para agendar serviços em menos de 60 segundos.', 'Nota cheia: explica a declaração de objetivo como meta do projeto e cita a meta de tempo (menos de 60 segundos) e a de etapas (3 passos), ou equivalente da própria aula. Metade: explica o objetivo sem citar nenhuma meta. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 2, 'Explique o que são as entregas obrigatórias (In) e dê um exemplo de tela', 0.4, 'As entregas obrigatórias (In) são o que será desenhado e construído. Exemplo: Tela 1 (Serviços), Tela 2 (Data e Hora) e Tela 3 (Confirmação com resumo).', 'Nota cheia: explica In como as entregas obrigatórias e dá um exemplo de tela do agendador (serviços, data e hora ou confirmação com resumo). Metade: explica In sem exemplo, ou dá exemplo sem explicar o conceito. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 3, 'Explique o que são os limites expressos (Out) e dê um exemplo de item excluído', 0.4, 'Os limites expressos (Out) são o que fica explicitamente fora do projeto. Exemplo: sem módulo de pagamento em cartão, sem autenticação por biometria e sem chat.', 'Nota cheia: explica Out como o que fica expressamente fora do projeto e dá um exemplo de item excluído (pagamento em cartão, biometria ou chat). Metade: explica Out sem exemplo, ou dá exemplo sem o conceito. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 1, 'Explique a parte Objetivo', 0.2, 'A parte Objetivo diz o que o sistema resolve, ou seja, o problema que a solução atende e a meta a alcançar.', 'Nota cheia: explica Objetivo como o que o sistema resolve (problema e meta). Metade: explica de forma vaga, como "a finalidade do projeto", sem ligar ao problema. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 2, 'Explique o que deve constar em Entregas e em Exclusões', 0.4, 'Entregas lista as telas que serão desenhadas (ex.: Serviços, Data e Hora, Confirmação). Exclusões lista o que não será construído, como pagamento online, rede social, jogos e chat aberto.', 'Nota cheia: explica que Entregas traz as telas a desenhar e Exclusões o que não será construído, com um exemplo de cada. Metade: explica apenas uma das duas partes ou sem exemplo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 3, 'Explique para que serve a parte Critérios de sucesso', 0.4, 'Critérios de sucesso dizem como avaliar se o projeto deu certo. Servem para a equipe medir o resultado e não apenas entregar as telas.', 'Nota cheia: explica que Critérios de sucesso definem como avaliar o resultado do projeto, para medir se ele funcionou. Metade: diz que são "metas" sem ligar à avaliação do resultado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 1, 'Explique o item Clareza com suas palavras', 0.2, 'Clareza é verificar se qualquer pessoa da equipe entende o que será entregue, sem ambiguidades.', 'Nota cheia: explica Clareza como entendimento do que será entregue por qualquer pessoa da equipe, sem ambiguidade. Metade: diz que é "o documento estar bem escrito" sem ligar ao entendimento da equipe. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 2, 'Explique o item Foco no Usuário e a relação com a dor principal diagnosticada na pesquisa', 0.4, 'Foco no Usuário verifica se o fluxo resolve 100% da dor principal diagnosticada na pesquisa (SA 1). No agendador, a dor principal é a demora e a confusão para agendar pela versão móvel.', 'Nota cheia: explica que o item verifica se o fluxo resolve a dor principal da pesquisa e cita a relação com ela (demora ou confusão no agendamento móvel). Metade: explica o item sem ligar à dor principal da pesquisa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 3, 'Explique o item Exequibilidade e o que ele verifica sobre a próxima aula', 0.4, 'Exequibilidade verifica se é possível desenhar os storyboards e protótipos de papel na próxima aula (Aula 17).', 'Nota cheia: explica que Exequibilidade verifica se o escopo permite fazer storyboard e protótipo em papel na próxima aula. Metade: explica como "se dá para fazer" sem citar storyboard, protótipo ou a próxima aula. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 1, 'Explique a etapa de análise cruzada entre os grupos', 0.2, 'Na análise cruzada, um grupo lê o escopo do outro para verificar se as fronteiras estão claras.', 'Nota cheia: explica que um grupo lê o escopo do outro para checar se as fronteiras estão claras. Metade: diz que os grupos "leem o trabalho do outro" sem ligar às fronteiras. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 2, 'Explique como identificar um inchaço escondido, como uma tela ou botão extra', 0.4, 'Para achar um inchaço escondido, o aluno procura telas ou botões extras que não aparecem na lista de entregas e que podem atrasar a entrega. Compara o que o escopo promete com o que as telas mostram.', 'Nota cheia: explica o procedimento (comparar as telas e botões com as entregas listadas) e cita o risco de atraso. Metade: diz para "procurar telas extras" sem o método de comparação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 3, 'Explique como sugerir um corte com justificativa técnica, respeitando a ideia do colega', 0.4, 'O aluno sugere o corte com justificativa técnica (prazo, complexidade, dados da pesquisa), reconhece a ideia do colega e propõe alternativa, como deixar a tela para uma versão futura.', 'Nota cheia: propõe o corte com justificativa técnica, reconhece a ideia do colega com respeito e oferece alternativa ou encaminhamento. Metade: sugere o corte com justificativa, mas sem respeito à ideia do colega ou sem alternativa. Zero: em branco, corte sem justificativa ou tom de confronto, errado ou fora do tema.'),
      (v_atividade, 16, 1, 'Explique por que o uso com pressa e pouca bateria deve ser considerado', 0.2, 'O uso com pressa e pouca bateria deve ser considerado porque os usuários acessam o agendamento assim. Uma tela cheia de entretenimento atrapalha quem só quer marcar o horário.', 'Nota cheia: cita o uso com pressa e pouca bateria como dado de uso real e liga a isso a necessidade de uma tela limpa. Metade: cita o uso com pressa sem ligar à tela ou sem dado de uso. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 2, 'Explique como elementos fora do escopo poluem o layout e elevam o abandono', 0.4, 'Elementos fora do escopo poluem o layout, deixam a tela carregada e aumentam o abandono, porque o usuário se distrai e desiste de agendar.', 'Nota cheia: explica que elementos fora do escopo poluem o layout e elevam o abandono, com a cadeia de distração e desistência. Metade: diz que "poluem a tela" sem ligar ao abandono. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 3, 'Explique uma alternativa de encaminhamento que mantenha o app limpo', 0.4, 'Uma alternativa é sugerir o recurso em redes sociais, mantendo o app limpo, ou guardá-lo para uma versão futura, sem colocá-lo na tela inicial.', 'Nota cheia: propõe um encaminhamento concreto que mantenha o app limpo (ex.: redes sociais ou versão futura) e explica por que. Metade: propõe alternativa sem explicar como mantém o app limpo. Zero: em branco, sem alternativa ou fora do tema.'),
      (v_atividade, 17, 1, 'Indique a primeira e a segunda etapas da jornada', 0.2, 'A primeira etapa é escolher o serviço desejado e a segunda é escolher a data e o horário disponível.', 'Nota cheia: indica a primeira etapa como escolha do serviço e a segunda como data e horário livre. Metade: indica apenas uma das duas corretamente. Zero: em branco, ordem errada ou fora do tema.'),
      (v_atividade, 17, 2, 'Indique a terceira etapa e explique por que a escolha do serviço vem antes da data', 0.4, 'A terceira etapa é informar os dados básicos de contato. O serviço vem antes da data porque o tempo estimado e os horários disponíveis dependem do atendimento escolhido.', 'Nota cheia: indica a terceira etapa como dados de contato e justifica que o serviço vem antes da data porque a duração e os horários dependem do atendimento. Metade: indica a etapa certa, mas justifica de forma vaga. Zero: em branco, ordem errada ou fora do tema.'),
      (v_atividade, 17, 3, 'Indique a etapa final e explique por que a confirmação com comprovante encerra a jornada', 0.4, 'A etapa final é visualizar a tela de confirmação com comprovante. Ela encerra a jornada porque dá ao usuário a segurança de que o agendamento foi feito, com a prova do que foi marcado.', 'Nota cheia: indica a confirmação com comprovante como etapa final e justifica pela segurança e prova do agendamento. Metade: indica a etapa final sem justificar. Zero: em branco, etapa errada ou fora do tema.'),
      (v_atividade, 18, 1, 'Explique por que o pagamento online fica para uma versão futura', 0.2, 'O pagamento online exige gateway bancário complexo, que demanda trabalho e suporte fora do alcance desta versão. Por isso, fica para a V2.', 'Nota cheia: explica que o pagamento exige gateway bancário complexo, com custo ou prazo fora da versão 1, e fica para uma versão futura. Metade: diz apenas que "é complexo" ou "fica para depois" sem o gateway. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 2, 'Explique por que a rede social e os jogos com pontos atrapalham o foco do agendamento', 0.4, 'A rede social, com feed de fotos, e os jogos com pontos distraem o foco do agendamento. A gamificação precoce sobrecarrega a tela e afasta o usuário da ação principal.', 'Nota cheia: explica que o feed e os jogos com pontos distraem do agendamento e sobrecarregam a tela. Metade: cita a distração sem explicar a sobrecarga ou sem citar os dois itens. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 3, 'Explique por que o chat aberto exige um suporte que o serviço não tem nesta versão', 0.4, 'O chat aberto exige atendimento ao vivo, que demanda uma equipe de suporte que o serviço não tem nesta versão. Por isso, fica fora da versão 1.', 'Nota cheia: explica que o chat ao vivo exige suporte que o serviço não tem nesta versão. Metade: diz que é "caro" ou "difícil" sem ligar ao suporte. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 1, 'Escreva a pergunta-chave sugerida na aula', 0.2, 'A pergunta-chave sugerida na aula é: "Qual problema do usuário ele resolve agora?".', 'Nota cheia: escreve a pergunta-chave (qual problema do usuário o recurso resolve agora), com as próprias palavras ou literal. Metade: escreve uma pergunta próxima, mas sem o foco no problema do usuário agora. Zero: em branco, outra pergunta sem relação ou fora do tema.'),
      (v_atividade, 19, 2, 'Explique o que significa dizer não com critério', 0.4, 'Dizer não com critério é recusar ou adiar um pedido com base em uma pergunta objetiva e em dados, e não por preferência pessoal. Permite explicar a decisão ao cliente.', 'Nota cheia: explica que dizer não com critério é recusar ou adiar com base em critério objetivo (problema do usuário, dados) e não em preferência. Metade: diz que é "recusar com argumento" sem o critério objetivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 3, 'Explique como a resposta a essa pergunta muda a decisão sobre o escopo', 0.4, 'Se o novo botão resolve um problema real e urgente do usuário, ele pode entrar no escopo. Se não resolve, ele fica fora ou para uma versão futura, e a decisão deixa de ser um sim ou não automático.', 'Nota cheia: explica que a resposta muda a decisão: problema real e relevante leva a entrar no escopo; sem problema, fica de fora. Metade: diz que a resposta ajuda a decidir, sem explicar a mudança concreta. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 1, 'Explique por que o escopo aprovado define quantas telas serão desenhadas', 0.2, 'O escopo aprovado define quantas telas serão desenhadas, porque lista as entregas obrigatórias. Exemplo: Serviços, Data e Hora e Confirmação.', 'Nota cheia: explica que o escopo lista as entregas e, por isso, define o número de telas a desenhar, com exemplo ou referência às telas do agendador. Metade: diz que "define o trabalho" sem ligar ao número de telas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 2, 'Explique o que é o storyboard e o que ele mostra sobre a jornada do usuário', 0.4, 'Storyboard é uma história em quadrinhos que mostra o usuário vivendo a jornada, passo a passo, e revela as etapas, as dúvidas e as dores dele.', 'Nota cheia: define storyboard como sequência de quadros que mostra a jornada do usuário e aponta o que revela (etapas, dúvidas ou dores). Metade: define storyboard sem ligar à jornada do usuário. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 3, 'Explique o que é o protótipo em papel e por que ele é feito antes do software digital', 0.4, 'Protótipo em papel simula os toques reais na interface com papel e caneta. É feito antes do software digital porque é rápido, barato e permite testar a ideia antes de programar.', 'Nota cheia: explica o protótipo em papel como simulação dos toques com papel e caneta e justifica por ser feito antes do digital (rápido, barato ou para testar antes de programar). Metade: explica o protótipo sem justificar a ordem. Zero: em branco, errado ou fora do tema.');
end $$;
